CREATE PROCEDURE "informix".sp_insertaimgpreviodigitalizacion(pUsuario CHAR(8), pIdFuncion CHAR(10), pCliente CHAR(20), pCodDocto CHAR(4), pImgFormato CHAR(3), pSvrRemoto CHAR(30))
		RETURNING CHAR(5) AS codret,
				  SMALLINT AS Secuencia;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(3);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE sSecuencia SMALLINT;
	DEFINE cQuery CHAR(1500);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET sSecuencia = 0;
	LET cQuery = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, sSecuencia;
		END EXCEPTION;

        SET ISOLATION TO DIRTY READ;


		IF pUsuario = '' OR pIdFuncion = '' OR pCliente  = '' OR pCodDocto = '' OR pImgFormato = '' OR pUsuario = '' OR pSvrRemoto = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, sSecuencia;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, sSecuencia;
		END IF;

		LET cQuery = "EXECUTE PROCEDURE" || " "||TRIM(pSvrRemoto)||"'informix'.inserta_img_previo_soc('"||cEmpresa|| "','" ||TRIM(pCliente)||"','" ||pCodDocto|| "','" ||TRIM(pImgFormato)|| "','" ||pUsuario||"');";

		PREPARE countQry FROM TRIM(cQuery);
		DECLARE countcur CURSOR FOR countQry;
		OPEN countcur;
		FETCH countcur INTO cCodRetSp, sSecuencia;
			LET iCodRetSp = cCodRetSp::INTEGER;
			IF iCodRetSp < 0 THEN
				RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP ';
			ELIF iCodRetSp = 110 THEN
				LET cCodRet = '00003';
			END IF;
			RETURN cCodRet, sSecuencia;
		CLOSE countcur;
		FREE countcur;
		FREE countQry;
	END;

END PROCEDURE
